type Cache struct {
	mu    sync.Mutex
	items map[string]int
	loads int
}

func (c *Cache) Get(key string) int {
	c.mu.Lock()
	v, ok := c.items[key]
	c.mu.Unlock()
	if ok {
		return v
	}
	runtime.Gosched() // stands in for a slow load
	v = len(key)
	c.mu.Lock()
	c.items[key] = v
	c.loads++
	c.mu.Unlock()
	return v
}
